T = 52
# Tiles defined by top-left corner (r, c)
tiles = [(0, 0), (1, 0), (0, 1), (1, 1)]

# We examine the grid from x=0 to T and y=0 to T (inclusive, so T+1 points)
# The grid coordinates run from 0 up to T. A cell (x, y) is covered if r <= x < r+T and c <= y < c+T.

coverage_counts = {}

# Iterate through points (x, y) in the boundary region of interest
for x in range(T + 1):
    for y in range(T + 1):
        count = 0
        for r_tile, c_tile in tiles:
            # Check if cell (x, y) is covered by the tile starting at (r_tile, c_tile)
            if r_tile <= x < r_tile + T and c_tile <= y < c_tile + T:
                count += 1

        if count > 0:
            coverage_counts[count] = coverage_counts.get(count, 0) + 1

print(f"Coverage counts found for {len(coverage_counts)} unique nonzero counts.")
for count, freq in coverage_counts.items():
    print(f"Count {count}: Frequency = {freq}")

max_k = 0
for count, freq in coverage_counts.items():
    if freq > max_k:
        max_k = freq
print(f"Maximum frequency k: {max_k}")
